WITH base AS (SELECT * FROM payments WHERE paid_at >= '2023-04-01' AND (method IS NOT NULL OR amount IS NOT NULL)), AmountBucketSummary AS (SELECT CASE WHEN amount >= 1540 THEN 'high' WHEN amount >= 680 THEN 'mid' ELSE 'low' END AS amount_bucket, MIN(amount) AS min_amount, ROUND(STDDEV(amount), 2) AS stddev_amount FROM base GROUP BY CASE WHEN amount >= 1540 THEN 'high' WHEN amount >= 680 THEN 'mid' ELSE 'low' END) SELECT * FROM AmountBucketSummary WHERE min_amount > 820
